 static int checks;static void ok(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}static ClassNode read(ZipFile z,String n)throws Exception{ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(n+".class")).readAllBytes()).accept(c,0);return c;}static boolean calls(ClassNode c,String method,String owner,String target){for(MethodNode m:c.methods)if(m.name.equals(method))for(AbstractInsnNode i:m.instructions)if(i instanceof MethodInsnNode n&&n.owner.equals(owner)&&n.name.equals(target))return true;return false;}
 public static void main(String[]a)throws Exception{try(ZipFile m=new ZipFile(a[0]);ZipFile h=new ZipFile(a[1])){String b="dev/zomboidmelee/boxing/",p="dev/zomboid/hordes/";ClassNode combat=read(m,"dev/zomboidmelee/mixin/VanillaCombatMixin");ok(calls(combat,"zpush$vanillaAttack",b+"Server20","vanilla"),"actual vanilla injection reaches damage preparation and cooldown");ok(!calls(combat,"zpush$vanillaAttack","com/armilp/ezweight/stamina/StaminaCommon","consume"),"no duplicated stamina handler");ClassNode shove=read(m,"dev/zomboidmelee/combat/ShoveCombat");ok(calls(shove,"push",b+"Shove20","hurt")&&calls(shove,"push",b+"Shove20","recoil")&&calls(shove,"push",b+"Net20","cue"),"actual V damage recoil and sync hooks");ClassNode hit=read(m,b+"BoxingHitEvents16");ok(calls(hit,"hit",b+"Boxing16","hit")&&calls(hit,"hit",b+"Server20","hit"),"server-confirmed hit cues alongside existing stun");ClassNode body=read(m,"dev/zomboidmelee/motion/BodyPush");ok(body.methods.stream().filter(q->q.name.equals("apply")).allMatch(q->q.instructions.getFirst().getOpcode()==177),"old conflicting body shove disabled");ClassNode zone=read(h,p+"ZoneReserve");for(String name:new String[]{"join","pre","room"})ok(calls(zone,name,p+"Budget49",name),"actual reserve admission/cap hook: "+name);ClassNode panel=read(h,p+"SimplePanel");for(String name:new String[]{"keys","labels","icons"})ok(calls(panel,"init",p+"Budget49",name),"actual slider array hook: "+name);ok(calls(read(h,p+"Population47"),"populate",p+"Budget49","full"),"full budget avoids expensive failed population attempts");for(ZipFile z:new ZipFile[]{m,h})ok(Collections.list(z.entries()).stream().noneMatch(e->e.getName().startsWith("net/minecraft/")),"compile-only APIs never ship");}System.out.println("NATIVE_MIXIN_V_RECOIL_PANEL_RESERVE_POPULATION_WIRING_CHECKS="+checks);}
